Copy & Swap Idiom:
class Buffer {
    int* data_;
    size_t size_;
public:
    Buffer(size_t s) : data_(new int[s]), size_(s) {}

    // Copy constructor
    Buffer(const Buffer& o)
        : data_(new int[o.size_]), size_(o.size_) {
        std::copy(o.data_, o.data_ + o.size_, data_);
    }

    // Destructor
    ~Buffer() { delete[] data_; }

    // Copy-and-swap assignment
    Buffer& operator=(Buffer o) noexcept {
        swap(*this, o);
        return *this;
    }

    friend void swap(Buffer& a, Buffer& b) noexcept {
        using std::swap;
        swap(a.data_, b.data_);
        swap(a.size_, b.size_);
    }
};

Rule of Five:
class String {
    char* data_;
    size_t len_;
public:
    // 1. Destructor
    ~String() { delete[] data_; }

    // 2. Copy constructor
    String(const String& o) : len_(o.len_),
        data_(new char[o.len_ + 1]) {
        std::copy(o.data_, o.data_ + o.len_ + 1, data_);
    }

    // 3. Copy assignment
    String& operator=(const String& o) {
        if (this != &o) {
            delete[] data_;
            len_ = o.len_;
            data_ = new char[len_ + 1];
            std::copy(o.data_, o.data_ + len_ + 1, data_);
        }
        return *this;
    }

    // 4. Move constructor
    String(String&& o) noexcept
        : data_(o.data_), len_(o.len_) {
        o.data_ = nullptr;
        o.len_ = 0;
    }

    // 5. Move assignment
    String& operator=(String&& o) noexcept {
        if (this != &o) {
            delete[] data_;
            data_ = o.data_;
            len_ = o.len_;
            o.data_ = nullptr;
            o.len_ = 0;
        }
        return *this;
    }
};

Move Semantics:
class Buffer {
public:
    Buffer(size_t s) : size(s), data(new int[s]) {}
    Buffer(Buffer&& other) noexcept
        : size(other.size), data(other.data) {
        other.data = nullptr;
        other.size = 0;
    }
    Buffer& operator=(Buffer&& other) noexcept {
        if (this != &other) {
            delete[] data;
            data = other.data;
            size = other.size;
            other.data = nullptr;
        }
        return *this;
    }
    ~Buffer() { delete[] data; }
private:
    size_t size;
    int* data;
};

std::vector<Buffer> bufs;
bufs.push_back(Buffer(100)); // moved, not copied

