std::expected:
#include <expected>
#include <string>
#include <iostream>

enum class Error { NotFound, PermissionDenied, Invalid };

std::expected<int, Error> divide(int a, int b) {
    if (b == 0) return std::unexpected(Error::Invalid);
    return a / b;
}

std::expected<int, Error> parse(const std::string& s) {
    try {
        return std::stoi(s);
    } catch (...) {
        return std::unexpected(Error::Invalid);
    }
}

// Monadic chaining
std::expected<int, Error> process(const std::string& a, const std::string& b) {
    return parse(a).and_then([&](int x) {
        return parse(b).and_then([&](int y) {
            return divide(x, y);
        });
    });
}

int main() {
    auto r1 = divide(10, 2);
    if (r1) std::cout << r1.value() << "\n";  // 5

    auto r2 = divide(10, 0);
    if (!r2) std::cout << "Error: " << static_cast<int>(r2.error()) << "\n";

    // value_or
    auto safe = divide(10, 0).value_or(-1);
    std::cout << safe << "\n";  // -1

    // Chaining
    auto res = process("10", "2");
    if (res) std::cout << res.value() << "\n";  // 5

    auto res2 = process("10", "abc");
    if (!res2) std::cout << "Parse failed\n";
}

