std::counting_semaphore:
#include <semaphore>

std::counting_semaphore<10> sem(0); // max 10, initial 0
std::vector<int> buffer;
std::mutex mtx;

void producer() {
    for (int i = 0; i < 20; ++i) {
        {
            std::lock_guard lk(mtx);
            buffer.push_back(i);
        }
        sem.release(); // signal consumer
    }
}

void consumer() {
    for (int i = 0; i < 20; ++i) {
        sem.acquire(); // wait for data
        std::lock_guard lk(mtx);
        int val = buffer.back();
        buffer.pop_back();
        std::cout << "got: " << val << std::endl;
    }
}

// Binary semaphore
std::binary_semaphore ping(0), pong(0);

std::thread t1([&] { ping.acquire(); /* ... */ pong.release(); });
std::thread t2([&] { pong.acquire(); /* ... */ ping.release(); });
ping.release(); // start

std::latch, std::barrier & std::semaphor:
#include <latch>
#include <barrier>
#include <semaphore>
#include <thread>
#include <vector>
#include <iostream>

// std::latch: single-use countdown
void demo_latch() {
    std::latch work_done(3);

    auto worker = [&] { 
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        work_done.count_down();
    };

    std::vector<std::jthread> threads;
    for (int i = 0; i < 3; ++i)
        threads.emplace_back(worker);

    work_done.wait();  // Block until all 3 count down
    std::cout << "All workers done\n";
}

// std::barrier: reusable synchronization
void demo_barrier() {
    std::barrier sync(3, [] { std::cout << "Phase complete\n"; });

    auto worker = [&sync](int id) {
        for (int phase = 0; phase < 3; ++phase) {
            std::this_thread::sleep_for(std::chrono::milliseconds(50 * id));
            sync.arrive_and_wait();  // Wait for all threads
        }
    };

    std::vector<std::jthread> threads;
    for (int i = 0; i < 3; ++i)
        threads.emplace_back(worker, i);
}

// std::counting_semaphore
void demo_semaphore() {
    std::counting_semaphore<3> pool(3);  // Max 3 concurrent

    auto worker = [&pool](int id) {
        pool.acquire();
        std::cout << "Thread " << id << " working\n";
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
        pool.release();
    };

    std::vector<std::jthread> threads;
    for (int i = 0; i < 6; ++i)
        threads.emplace_back(worker, i);
}

int main() {
    demo_latch();
    demo_barrier();
    demo_semaphore();
}

