noexcept & noexcept Specifier Deep:
#include <iostream>
#include <vector>
#include <type_traits>

// noexcept specification
void safe_func() noexcept {
    std::cout << "This won't throw\n";
}

void maybe_throws() {
    throw std::runtime_error("oops");
}

// Conditional noexcept
void conditional_func() noexcept(noexcept(maybe_throws())) {
    maybe_throws();
}

// noexcept operator
void demo_noexcept_op() {
    std::cout << std::boolalpha;
    std::cout << "safe_func is noexcept: " << noexcept(safe_func()) << "\n";
    std::cout << "maybe_throws is noexcept: " << noexcept(maybe_throws()) << "\n";
}

// Move operations should be noexcept
struct MyData {
    int* data;

    MyData() : data(new int[100]) {}
    ~MyData() { delete[] data; }

    MyData(MyData&& other) noexcept
        : data(std::exchange(other.data, nullptr)) {}

    MyData& operator=(MyData&& other) noexcept {
        if (this != &other) {
            delete[] data;
            data = std::exchange(other.data, nullptr);
        }
        return *this;
    }

    MyData(const MyData&) = delete;
    MyData& operator=(const MyData&) = delete;
};

// noexcept affects container performance
void demo_vector_safety() {
    std::cout << "MyData move is noexcept: "
              << std::is_nothrow_move_constructible_v<MyData> << "\n";

    std::vector<MyData> vec;
    vec.push_back(MyData{});  // Uses move if noexcept, copy otherwise
}

int main() {
    safe_func();
    demo_noexcept_op();
    demo_vector_safety();
}

