#include <variant>
#include <iostream>
#include <string>

// can hold int, double, or std::string
using Value = std::variant<int, double, std::string>;

int main() {
    Value v = 42;  // holds int
    std::cout << std::get<int>(v) << std::endl;  // extracts int

    v = 3.14;  // now holds double
    std::cout << std::get<double>(v) << std::endl;

    v = "hello";  // now holds string

    // visitor dispatches on current type
    auto visitor = [](auto&& arg) {
        std::cout << arg << std::endl;
    };
    std::visit(visitor, v);  // prints "hello"

    // safe access without throw
    if (auto* s = std::get_if<std::string>(&v)) {
        std::cout << "String: " << *s << std::endl;
    }

    std::cout << "index: " << v.index() << std::endl;  // 2
    return 0;
}

