Design Patterns: Strategy & Observer:
#include <functional>
#include <memory>
#include <vector>
#include <iostream>
#include <algorithm>

// === Strategy Pattern ===
struct SortStrategy {
    virtual void sort(std::vector<int>& v) const = 0;
    virtual ~SortStrategy() = default;
};

struct BubbleSort final : SortStrategy {
    void sort(std::vector<int>& v) const override {
        // O(n^2) simple sort
    }
};

struct StdSort final : SortStrategy {
    void sort(std::vector<int>& v) const override {
        std::sort(v.begin(), v.end());  // O(n log n)
    }
};

struct Context {
    std::unique_ptr<SortStrategy> strategy;
    void execute(std::vector<int>& v) const {
        strategy->sort(v);  // polymorphic dispatch
    }
};

// === Observer Pattern ===
struct Observer {
    virtual void update(int new_state) = 0;
    virtual ~Observer() = default;
};

class Subject {
    std::vector<std::weak_ptr<Observer>> observers_;
    int state_ = 0;
public:
    void attach(std::shared_ptr<Observer> o) {
        observers_.push_back(std::move(o));
    }
    void set_state(int s) {
        state_ = s;
        // notify all observers
        for (auto& w : observers_)
            if (auto sp = w.lock()) sp->update(state_);
    }
};

