// 1. Reserve before bulk push_back
std::vector<int> build_vector(size_t n) {
    std::vector<int> v;
    v.reserve(n);  // one allocation, no reallocs
    for (size_t i = 0; i < n; ++i)
        v.push_back(i);
    return v;  // NRVO: elides copy
