fmtlib & spdlog:
#include <fmt/core.h>
#include <fmt/chrono.h>
#include <spdlog/spdlog.h>
#include <spdlog/sinks/basic_file_sink.h>
#include <chrono>

// fmtlib formatting
struct Point {
    int x, y;
};

template <>
struct fmt::formatter<Point> {
    constexpr auto parse(format_parse_context& ctx) { return ctx.begin(); }

    template <typename FormatContext>
    auto format(const Point& p, FormatContext& ctx) {
        return fmt::format_to(ctx.out(), "({}, {})", p.x, p.y);
    }
};

int main() {
    // fmtlib examples
    fmt::print("Hello {}!\n", "world");
    fmt::print("{:>10} {:06d}\n", "right", 42);
    fmt::print("{:.2f}\n", 3.14159);

    // Chrono formatting
    auto now = std::chrono::system_clock::now();
    fmt::print("{:%Y-%m-%d %H:%M:%S}\n", now);

    // Custom type
    Point p{3, 4};
    fmt::print("Point: {}\n", p);

    // spdlog logging
    spdlog::info("Application started");
    spdlog::warn("Memory usage at 90%");
    spdlog::error("Failed to open file: {}", "config.txt");

    // File logger
    auto file_logger = spdlog::basic_logger_mt("file", "app.log");
    file_logger->info("Writing to file");
    file_logger->flush();

    // Pattern formatting
    spdlog::set_pattern("[%Y-%m-%d %H:%M:%S] [%^%l%$] %v");
    spdlog::info("Styled log message");

    // Disabled at compile time
    spdlog::set_level(spdlog::level::warn);
    spdlog::debug("This won't be printed");  // Filtered out
}
